// Si folderId fourni dans Start (cas doublon) → utilise-le
// Sinon → utilise l'ID du dossier créé par "Create folder" (cas nouveau client)
let folderId;
try {
  folderId = $('Start').first().json.folderId || $('Create folder').first().json.id;
} catch(e) {
  folderId = $('Start').first().json.folderId;
}

const fichiers = $('Start').first().json.JSDdupliquer__allItems.map(item => item.json);

return fichiers.map(f => ({
  json: {
    folderId,
    filename: f.filename,
    messageId: f.messageId,
    attachmentId: f.attachmentId,
    hash: f.hash  // hash Gmail MD5 hex pour stockage dans description Drive
  }
}));

const items = $input.all();
const results = [];
const today = new Date().toISOString().split('T')[0];

// ============ RECHERCHE GLOBALE DU NOM DE SOCIÉTÉ ============
function findNomSociete(obj) {
  if (obj === null || obj === undefined) return null;

  if (typeof obj === 'string') {
    const match = obj.match(/"nom_societe"\s*:\s*"([^"]+)"/);
    if (match) return match[1];
    try {
      return findNomSociete(JSON.parse(obj));
    } catch (e) { return null; }
  }

  if (Array.isArray(obj)) {
    for (const el of obj) {
      const found = findNomSociete(el);
      if (found) return found;
    }
    return null;
  }

  if (typeof obj === 'object') {
    if (typeof obj.nom_societe === 'string' && obj.nom_societe.trim()) {
      return obj.nom_societe;
    }
    for (const key of Object.keys(obj)) {
      const found = findNomSociete(obj[key]);
      if (found) return found;
    }
  }

  return null;
}

let nomSociete = 'Societe';

// Chercher dans TOUS les items d'entrée
for (let i = 0; i < items.length; i++) {
  console.log(`===== ITEM ${i} JSON COMPLET =====`);
  console.log(JSON.stringify(items[i].json));

  const found = findNomSociete(items[i].json);
  if (found) {
    nomSociete = found.trim().replace(/\s+/g, '_');
    console.log(`>>> nom_societe trouvé dans item ${i}: ${nomSociete}`);
    break;
  }
}

// Si toujours rien, chercher dans les nœuds précédents possibles
if (nomSociete === 'Societe') {
  const nodesToTry = ['Start', 'When Executed by Another Workflow', 'AI Agent', 'Agent'];
  for (const nodeName of nodesToTry) {
    try {
      const nodeData = $(nodeName).all();
      for (const nd of nodeData) {
        const found = findNomSociete(nd.json);
        if (found) {
          nomSociete = found.trim().replace(/\s+/g, '_');
          console.log(`>>> nom_societe trouvé dans le nœud "${nodeName}": ${nomSociete}`);
          break;
        }
      }
      if (nomSociete !== 'Societe') break;
    } catch (e) {
      console.log(`Nœud "${nodeName}" inaccessible: ${e.message}`);
    }
  }
}

console.log('========================================');
console.log('>>> NOM SOCIÉTÉ FINAL:', nomSociete);
console.log('========================================');

