// ============ TRAITEMENT DES FICHIERS ============
for (const item of items) {
  const buffer = await this.helpers.getBinaryDataBuffer(items.indexOf(item), 'data');
  const gmailResponse = JSON.parse(buffer.toString('utf-8'));

  const base64Standard = gmailResponse.data.replace(/-/g, '+').replace(/_/g, '/');
  const pdfBuffer = Buffer.from(base64Standard, 'base64');

  const driveHash = md5(pdfBuffer);

  const nomActuel = item.json.filename || 'document.pdf';
  const extension = nomActuel.includes('.') ? nomActuel.split('.').pop() : 'pdf';
  const typeDoc = nomActuel.includes('.') ? nomActuel.substring(0, nomActuel.lastIndexOf('.')) : nomActuel;

  const nouveauNom = `${today}_${nomSociete}_${typeDoc}.${extension}`;

  results.push({
    json: {
      ...item.json,
      filename: nouveauNom,
      driveHash
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        pdfBuffer,
        nouveauNom,
        item.json.mimeType || 'application/pdf'
      )
    }
  });
}

return results;
